diff --git a/src/host_control/link.c b/src/host_control/link.c
new file mode 100644
index 00000000..d1af893a
--- /dev/null
+++ b/src/host_control/link.c
@@ -0,0 +1,212 @@
+#include "host_control/link.h"
+
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include "core/json.h"
+#include "core/package_library.h"
+#include "core/util.h"
+#include "platform/thread.h"
+
+static const VdHostControlLinkReply LINK_OK = {200, NULL, NULL};
+static const VdHostControlLinkReply LINK_MALFORMED = {
+    400, "malformed_request",
+    "Link request must be a JSON object with a number protocolVersion and string id, name and url."};
+static const VdHostControlLinkReply LINK_UNSUPPORTED_VERSION = {400, "unsupported_protocol_version",
+                                                                "VitaDeck speaks Host Control protocol version 1."};
+static const VdHostControlLinkReply LINK_INVALID = {
+    422, "invalid_payload", "Link needs an id, a name of 1 to 64 bytes, and an http:// url of at most 255 bytes."};
+
+// jimp keeps the string's terminator in string_count, so an embedded NUL shows up as a shorter strlen.
+static bool valid_text(const Jimp *jimp, size_t max, bool allow_space)
+{
+    size_t len = strlen(jimp->string);
+    if (len == 0 || len > max || len + 1 != jimp->string_count) return false;
+    for (const unsigned char *p = (const unsigned char *)jimp->string; *p; p++) {
+        if (*p < 0x20 || *p == 0x7f || (*p == ' ' && !allow_space)) return false;
+    }
+    return true;
+}
+
+// Reads a string member into out when it is valid; false only when the member is not a string.
+static bool read_field(Jimp *jimp, char *out, size_t max, bool allow_space, bool *valid)
+{
+    if (!jimp_string(jimp)) return false;
+    *valid = valid_text(jimp, max, allow_space);
+    if (*valid) memcpy(out, jimp->string, strlen(jimp->string) + 1);
+    return true;
+}
+
+typedef struct {
+    bool version_seen;
+    double version;
+    bool id_valid, name_valid, url_valid;
+} LinkFields;
+
+// Parses one link object. False when it is not an object of the right member types.
+static bool parse_link_object(Jimp *jimp, VdHostControlLink *out, LinkFields *fields)
+{
+    memset(out, 0, sizeof(*out));
+    memset(fields, 0, sizeof(*fields));
+    if (!jimp_object_begin(jimp)) return false;
+    while (jimp_object_member(jimp)) {
+        bool ok;
+        if (strcmp(jimp->string, "protocolVersion") == 0) {
+            ok = jimp_number(jimp);
+            fields->version_seen = ok;
+            fields->version = jimp->number;
+        } else if (strcmp(jimp->string, "id") == 0) {
+            ok = read_field(jimp, out->id, VD_HOST_CONTROL_ID_MAX, false, &fields->id_valid);
+        } else if (strcmp(jimp->string, "name") == 0) {
+            ok = read_field(jimp, out->name, VD_HOST_CONTROL_NAME_MAX, true, &fields->name_valid);
+        } else if (strcmp(jimp->string, "url") == 0) {
+            ok = read_field(jimp, out->url, VD_HOST_CONTROL_URL_MAX, false, &fields->url_valid);
+            if (ok && fields->url_valid) {
+                fields->url_valid = strncmp(out->url, "http://", 7) == 0 && out->url[7] != '\0';
+            }
+        } else {
+            ok = json_skip_value(jimp);
+        }
+        if (!ok) return false;
+    }
+    return jimp_object_end(jimp);
+}
+
+static bool link_fields_valid(const LinkFields *fields)
+{
+    return fields->id_valid && fields->name_valid && fields->url_valid;
+}
+
+VdHostControlLinkReply host_control_link_parse(const char *json, VdHostControlLink *out)
+{
+    Jimp jimp = {0};
+    jimp_begin(&jimp, "link request", json, strlen(json));
+    LinkFields fields;
+    bool parsed = parse_link_object(&jimp, out, &fields);
+    free(jimp.string);
+
+    if (!parsed) return LINK_MALFORMED;
+    if (!fields.version_seen || fields.version != VD_HOST_CONTROL_PROTOCOL_VERSION) return LINK_UNSUPPORTED_VERSION;
+    if (!link_fields_valid(&fields)) return LINK_INVALID;
+    return LINK_OK;
+}
+
+static vd_mutex *g_mutex;
+static char g_path[VD_PATH_MAX];
+static VdHostControlLink g_links[VD_HOST_CONTROL_MAX_LINKS];
+static int g_count;
+
+static char *links_to_json(const VdHostControlLink *links, int count)
+{
+    // Every escaped byte takes at most 6; the rest is punctuation and member names.
+    size_t size = 3 + (size_t)count * (sizeof(VdHostControlLink) * 6 + 64);
+    char *json = malloc(size);
+    if (!json) return NULL;
+    size_t used = 0;
+    json[used++] = '[';
+    for (int i = 0; i < count; i++) {
+        char id[sizeof(links[i].id) * 6];
+        char name[sizeof(links[i].name) * 6];
+        char url[sizeof(links[i].url) * 6];
+        json_escape(id, sizeof(id), links[i].id);
+        json_escape(name, sizeof(name), links[i].name);
+        json_escape(url, sizeof(url), links[i].url);
+        used += (size_t)snprintf(json + used, size - used, "%s{\"id\":\"%s\",\"name\":\"%s\",\"url\":\"%s\"}",
+                                 i > 0 ? "," : "", id, name, url);
+    }
+    json[used++] = ']';
+    json[used] = '\0';
+    return json;
+}
+
+static bool persist(const VdHostControlLink *links, int count)
+{
+    if (count == 0) return vd_remove_replaced_file(g_path);
+    char *json = links_to_json(links, count);
+    bool ok = json && vd_replace_file(g_path, json, strlen(json));
+    free(json);
+    return ok;
+}
+
+static void load(void)
+{
+    g_count = 0;
+    size_t len = 0;
+    bool found = false;
+    char *json = vd_read_replaced_file(g_path, &len, &found);
+    if (!json) return;
+
+    Jimp jimp = {0};
+    jimp_begin(&jimp, g_path, json, len);
+    if (jimp_array_begin(&jimp)) {
+        while (g_count < VD_HOST_CONTROL_MAX_LINKS && jimp_array_item(&jimp)) {
+            LinkFields fields;
+            if (!parse_link_object(&jimp, &g_links[g_count], &fields)) break;
+            if (link_fields_valid(&fields)) g_count++;
+        }
+    }
+    free(jimp.string);
+    free(json);
+}
+
+bool host_control_links_init(const char *data_root)
+{
+    if (!g_mutex) g_mutex = vd_mutex_create();
+    if (!g_mutex || !vd_join_path(g_path, sizeof(g_path), data_root, "host-control-links.json")) return false;
+    vd_mutex_lock(g_mutex);
+    load();
+    vd_mutex_unlock(g_mutex);
+    return true;
+}
+
+bool host_control_links_save(const VdHostControlLink *link)
+{
+    VdHostControlLink next[VD_HOST_CONTROL_MAX_LINKS];
+    int count = 0;
+    next[count++] = *link;
+    vd_mutex_lock(g_mutex);
+    for (int i = 0; i < g_count && count < VD_HOST_CONTROL_MAX_LINKS; i++) {
+        if (strcmp(g_links[i].id, link->id) != 0) next[count++] = g_links[i];
+    }
+    bool ok = persist(next, count);
+    if (ok) {
+        memcpy(g_links, next, sizeof(next[0]) * (size_t)count);
+        g_count = count;
+    }
+    vd_mutex_unlock(g_mutex);
+    return ok;
+}
+
+bool host_control_links_forget(const char *id)
+{
+    VdHostControlLink next[VD_HOST_CONTROL_MAX_LINKS];
+    int count = 0;
+    vd_mutex_lock(g_mutex);
+    for (int i = 0; i < g_count; i++) {
+        if (strcmp(g_links[i].id, id) != 0) next[count++] = g_links[i];
+    }
+    bool ok = count < g_count && persist(next, count);
+    if (ok) {
+        memcpy(g_links, next, sizeof(next[0]) * (size_t)count);
+        g_count = count;
+    }
+    vd_mutex_unlock(g_mutex);
+    return ok;
+}
+
+int host_control_links_list(VdHostControlLink *out, int max)
+{
+    vd_mutex_lock(g_mutex);
+    int count = g_count < max ? g_count : max;
+    memcpy(out, g_links, sizeof(out[0]) * (size_t)count);
+    vd_mutex_unlock(g_mutex);
+    return count;
+}
+
+char *host_control_links_json(void)
+{
+    vd_mutex_lock(g_mutex);
+    char *json = links_to_json(g_links, g_count);
+    vd_mutex_unlock(g_mutex);
+    return json;
+}

diff --git a/src/host_control/link.h b/src/host_control/link.h
new file mode 100644
index 00000000..838f945f
--- /dev/null
+++ b/src/host_control/link.h
@@ -0,0 +1,39 @@
+#ifndef VD_HOST_CONTROL_LINK_H
+#define VD_HOST_CONTROL_LINK_H
+
+#include <stdbool.h>
+#include <stddef.h>
+
+#define VD_HOST_CONTROL_PROTOCOL_VERSION 1
+#define VD_HOST_CONTROL_MAX_LINKS 4
+#define VD_HOST_CONTROL_ID_MAX 64
+#define VD_HOST_CONTROL_NAME_MAX 64
+#define VD_HOST_CONTROL_URL_MAX 255
+
+// One computer whose Host Companion linked with this VitaDeck.
+typedef struct {
+    char id[VD_HOST_CONTROL_ID_MAX + 1];
+    char name[VD_HOST_CONTROL_NAME_MAX + 1];
+    char url[VD_HOST_CONTROL_URL_MAX + 1];
+} VdHostControlLink;
+
+// How the link endpoint answers a request: 200 with a NULL code, or a wire error code and message.
+typedef struct {
+    int status;
+    const char *code;
+    const char *message;
+} VdHostControlLinkReply;
+
+// Validates a NUL-terminated `POST /link` body. Pure; `out` is only meaningful when the status is 200.
+VdHostControlLinkReply host_control_link_parse(const char *json, VdHostControlLink *out);
+
+// The Host Control Links, newest first, kept in <data root>/host-control-links.json. Safe from any thread.
+bool host_control_links_init(const char *data_root);
+// Puts the link first, replacing the entry with its id or else dropping the oldest past the cap, and persists.
+bool host_control_links_save(const VdHostControlLink *link);
+bool host_control_links_forget(const char *id);
+int host_control_links_list(VdHostControlLink *out, int max);
+// The list as a malloc'd JSON array of {id,name,url}, newest first, or NULL when out of memory.
+char *host_control_links_json(void);
+
+#endif /* VD_HOST_CONTROL_LINK_H */

diff --git a/src/host_control/listener.c b/src/host_control/listener.c
new file mode 100644
index 00000000..07aee169
--- /dev/null
+++ b/src/host_control/listener.c
@@ -0,0 +1,239 @@
+#include "host_control/listener.h"
+
+#include <arpa/inet.h>
+#include <netinet/in.h>
+#include <stdio.h>
+#include <string.h>
+#include <sys/socket.h>
+#include <sys/time.h>
+#include <unistd.h>
+#include "arena.h"
+#include "core/util.h"
+#include "net/http.h"
+#include "platform/lan_address.h"
+
+#define VD_HOST_CONTROL_DEFAULT_PORT 8798
+#define VD_HOST_CONTROL_PORT_TRIES 10
+#define VD_HOST_CONTROL_MAX_BODY (64 * 1024)
+#define VD_HOST_CONTROL_RECV_TIMEOUT_SEC 2
+
+static void set_message(VdHostControlListener *listener, const char *message)
+{
+    vd_mutex_lock(listener->mutex);
+    snprintf(listener->last_message, sizeof(listener->last_message), "%s", message);
+    vd_mutex_unlock(listener->mutex);
+}
+
+static void reject(VdHostControlListener *listener, int fd, int status, const char *code, const char *message)
+{
+    http_send_json_error(fd, status, code, message);
+    char line[sizeof(listener->last_message)];
+    snprintf(line, sizeof(line), "Link rejected: %s", message);
+    set_message(listener, line);
+}
+
+// Answers one connection. True when it stored a link.
+static bool handle_connection(VdHostControlListener *listener, int fd)
+{
+    char first[256];
+    ssize_t n = recv(fd, first, sizeof(first) - 1, MSG_PEEK);
+    if (n <= 0) return false;
+    first[n] = '\0';
+
+    char method[16] = {0};
+    char path[128] = {0};
+    sscanf(first, "%15s %127s", method, path);
+    if (strcmp(path, "/link") != 0) {
+        http_send_simple_response(fd, 404, "Not Found", "text/plain", "Not Found");
+        return false;
+    }
+    if (strcmp(method, "POST") != 0) {
+        http_send_simple_response(fd, 405, "Method Not Allowed", "text/plain", "Method Not Allowed");
+        return false;
+    }
+
+    Arena arena = {0};
+    bool linked = false;
+    char *headers = NULL;
+    unsigned char *body = NULL;
+    size_t body_len = 0;
+    int read_error = 400;
+    if (!http_read_request(&arena, fd, VD_HOST_CONTROL_MAX_BODY, &headers, &body, &body_len, &read_error)) {
+        if (read_error == 413) {
+            reject(listener, fd, 413, "payload_too_large", "Link request exceeds 64 KiB.");
+            http_drain_rejected_request(fd, VD_HOST_CONTROL_MAX_BODY);
+        } else {
+            reject(listener, fd, 400, "malformed_request", "Could not read link request.");
+        }
+        goto done;
+    }
+    if (!http_content_type_is(headers, "application/json")) {
+        reject(listener, fd, 400, "malformed_request", "Link request must be application/json.");
+        goto done;
+    }
+
+    VdHostControlLink link;
+    VdHostControlLinkReply reply = host_control_link_parse((const char *)body, &link);
+    if (reply.status != 200) {
+        reject(listener, fd, reply.status, reply.code, reply.message);
+        goto done;
+    }
+    if (!host_control_links_save(&link)) {
+        reject(listener, fd, 500, "command_failed", "VitaDeck could not save the link.");
+        goto done;
+    }
+
+    http_send_response(fd, 200, "OK", "application/json", "{\"ok\":true}");
+    vd_mutex_lock(listener->mutex);
+    listener->link_pending = true;
+    listener->last_link = link;
+    vd_mutex_unlock(listener->mutex);
+    linked = true;
+
+done:
+    arena_free(&arena);
+    return linked;
+}
+
+static void *listener_thread(void *raw)
+{
+    VdHostControlListener *listener = raw;
+    while (listener->running) {
+        struct sockaddr_in client;
+        socklen_t client_len = sizeof(client);
+        int fd = accept(listener->listen_fd, (struct sockaddr *)&client, &client_len);
+        if (fd < 0) {
+            if (listener->running) vd_thread_yield();
+            continue;
+        }
+        struct timeval timeout = {.tv_sec = VD_HOST_CONTROL_RECV_TIMEOUT_SEC};
+        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
+        vd_mutex_lock(listener->mutex);
+        bool stopping = !listener->running;
+        if (!stopping) listener->client_fd = fd;
+        vd_mutex_unlock(listener->mutex);
+        if (stopping) {
+            close(fd);
+            break;
+        }
+        bool linked = handle_connection(listener, fd);
+        vd_mutex_lock(listener->mutex);
+        listener->client_fd = -1;
+        vd_mutex_unlock(listener->mutex);
+        close(fd);
+        if (linked) listener->running = false;
+    }
+    return NULL;
+}
+
+void host_control_listener_init(VdHostControlListener *listener)
+{
+    memset(listener, 0, sizeof(*listener));
+    listener->listen_fd = -1;
+    listener->client_fd = -1;
+    listener->mutex = vd_mutex_create();
+}
+
+bool host_control_listener_start(VdHostControlListener *listener, char *error, size_t error_size)
+{
+    if (listener->running) return true;
+    host_control_listener_stop(listener);
+    listener->link_pending = false;
+    listener->last_message[0] = '\0';
+
+    for (int i = 0; i < VD_HOST_CONTROL_PORT_TRIES; i++) {
+        int fd = socket(AF_INET, SOCK_STREAM, 0);
+        if (fd < 0) continue;
+        int yes = 1;
+        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
+
+        struct sockaddr_in addr;
+        memset(&addr, 0, sizeof(addr));
+        addr.sin_family = AF_INET;
+        addr.sin_addr.s_addr = htonl(INADDR_ANY);
+        addr.sin_port = htons((uint16_t)(VD_HOST_CONTROL_DEFAULT_PORT + i));
+        if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) != 0 || listen(fd, 4) != 0) {
+            close(fd);
+            continue;
+        }
+
+        listener->listen_fd = fd;
+        char ip[48];
+        lan_address_detect(ip, sizeof(ip));
+        snprintf(listener->address, sizeof(listener->address), "%s:%d", ip, VD_HOST_CONTROL_DEFAULT_PORT + i);
+        listener->running = true;
+        listener->thread = vd_thread_create(listener_thread, listener);
+        if (!listener->thread) {
+            listener->running = false;
+            close(fd);
+            listener->listen_fd = -1;
+            vd_set_error(error, error_size, "Could not start the Host Control Link Listener thread.");
+            return false;
+        }
+        return true;
+    }
+
+    vd_set_error(error, error_size, "Could not bind the Host Control Link Listener on ports 8798-8807.");
+    return false;
+}
+
+void host_control_listener_stop(VdHostControlListener *listener)
+{
+    listener->running = false;
+    if (listener->listen_fd >= 0) {
+        shutdown(listener->listen_fd, SHUT_RDWR);
+        close(listener->listen_fd);
+        listener->listen_fd = -1;
+    }
+    if (listener->mutex) {
+        vd_mutex_lock(listener->mutex);
+        if (listener->client_fd >= 0) shutdown(listener->client_fd, SHUT_RDWR);
+        vd_mutex_unlock(listener->mutex);
+    }
+    if (listener->thread) {
+        vd_thread_join(listener->thread);
+        vd_thread_destroy(listener->thread);
+        listener->thread = NULL;
+    }
+}
+
+void host_control_listener_destroy(VdHostControlListener *listener)
+{
+    host_control_listener_stop(listener);
+    vd_mutex_destroy(listener->mutex);
+    listener->mutex = NULL;
+}
+
+bool host_control_listener_is_running(const VdHostControlListener *listener)
+{
+    return listener->running;
+}
+
+const char *host_control_listener_address(const VdHostControlListener *listener)
+{
+    return listener->address;
+}
+
+bool host_control_listener_take_link(VdHostControlListener *listener, VdHostControlLink *out)
+{
+    vd_mutex_lock(listener->mutex);
+    bool pending = listener->link_pending;
+    if (pending) {
+        *out = listener->last_link;
+        listener->link_pending = false;
+    }
+    vd_mutex_unlock(listener->mutex);
+    return pending;
+}
+
+bool host_control_listener_take_message(VdHostControlListener *listener, char *out, size_t out_size)
+{
+    vd_mutex_lock(listener->mutex);
+    bool has_message = listener->last_message[0] != '\0';
+    if (has_message) {
+        snprintf(out, out_size, "%s", listener->last_message);
+        listener->last_message[0] = '\0';
+    }
+    vd_mutex_unlock(listener->mutex);
+    return has_message;
+}

diff --git a/src/host_control/listener.h b/src/host_control/listener.h
new file mode 100644
index 00000000..cf2e8cd1
--- /dev/null
+++ b/src/host_control/listener.h
@@ -0,0 +1,36 @@
+#ifndef VD_HOST_CONTROL_LISTENER_H
+#define VD_HOST_CONTROL_LISTENER_H
+
+#include <stdbool.h>
+#include <stddef.h>
+#include "host_control/link.h"
+#include "platform/thread.h"
+
+// Accepts one Host Control Link on `POST /link`, then stops itself.
+typedef struct {
+    vd_thread *thread;
+    vd_mutex *mutex;
+    volatile bool running;
+    int listen_fd;
+    // The connection being answered, so stop can cut off a client that sends slowly. -1 when none.
+    int client_fd;
+    char address[64];
+    bool link_pending;
+    VdHostControlLink last_link;
+    char last_message[256];
+} VdHostControlListener;
+
+void host_control_listener_init(VdHostControlListener *listener);
+bool host_control_listener_start(VdHostControlListener *listener, char *error, size_t error_size);
+// Joins the thread and closes the socket; also needed after the listener stopped itself.
+void host_control_listener_stop(VdHostControlListener *listener);
+void host_control_listener_destroy(VdHostControlListener *listener);
+bool host_control_listener_is_running(const VdHostControlListener *listener);
+// `<ip>:<port>` while bound.
+const char *host_control_listener_address(const VdHostControlListener *listener);
+// True once per successful link, with the link the Host Companion sent.
+bool host_control_listener_take_link(VdHostControlListener *listener, VdHostControlLink *out);
+// The latest rejected link request, once.
+bool host_control_listener_take_message(VdHostControlListener *listener, char *out, size_t out_size);
+
+#endif /* VD_HOST_CONTROL_LISTENER_H */

diff --git a/src/jslib/host_control.c b/src/jslib/host_control.c
new file mode 100644
index 00000000..10612615
--- /dev/null
+++ b/src/jslib/host_control.c
@@ -0,0 +1,20 @@
+#include "jslib_internal.h"
+#include "host_control/link.h"
+
+// Read live on every Host Control call, so a link made while a Deck App runs takes effect at once.
+static JSValue js_native_get_host_control_links(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
+{
+    (void)this_val;
+    (void)argc;
+    (void)argv;
+    char *json = host_control_links_json();
+    if (!json) return JS_ThrowOutOfMemory(ctx);
+    JSValue result = JS_NewString(ctx, json);
+    free(json);
+    return result;
+}
+
+void register_js_host_control(JSContext *ctx)
+{
+    js_set_global_function(ctx, "nativeGetHostControlLinks", js_native_get_host_control_links, 0);
+}

